CREATE SEQUENCE seq_suppliers INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 19 NO CYCLE;;
CREATE SEQUENCE seq_staff INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 52 NO CYCLE;;
CREATE SEQUENCE seq_reviews INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 2 NO CYCLE;;
CREATE SEQUENCE seq_recipes INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 29 NO CYCLE;;
CREATE SEQUENCE seq_recipe_items INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 172 NO CYCLE;;
CREATE SEQUENCE seq_payments INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 18337 NO CYCLE;;
CREATE SEQUENCE seq_pos_shifts INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 356 NO CYCLE;;
CREATE SEQUENCE seq_order_items INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 26767 NO CYCLE;;
CREATE SEQUENCE seq_orders INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 18814 NO CYCLE;;
CREATE SEQUENCE seq_subscriptions INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 125 NO CYCLE;;
CREATE SEQUENCE seq_purchase_order_items INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE SEQUENCE seq_ingredient_lots INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 751 NO CYCLE;;
CREATE SEQUENCE seq_delivery_slots INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 4261 NO CYCLE;;
CREATE SEQUENCE seq_day_closes INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE SEQUENCE seq_ingredients INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 33 NO CYCLE;;
CREATE SEQUENCE seq_customers INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 4394 NO CYCLE;;
CREATE SEQUENCE seq_build_components INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 28925 NO CYCLE;;
CREATE SEQUENCE seq_purchase_orders INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE SEQUENCE seq_component_batches INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 5447 NO CYCLE;;
CREATE SEQUENCE seq_builds INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 12546 NO CYCLE;;
CREATE TABLE suppliers(id INTEGER DEFAULT(nextval('seq_suppliers')) PRIMARY KEY, "name" VARCHAR NOT NULL, contact VARCHAR, lead_time_days INTEGER, terms VARCHAR);;
CREATE TABLE staff(id INTEGER DEFAULT(nextval('seq_staff')) PRIMARY KEY, "name" VARCHAR NOT NULL, "role" VARCHAR DEFAULT('baker') NOT NULL);;
CREATE TABLE recipes(id INTEGER DEFAULT(nextval('seq_recipes')) PRIMARY KEY, component_type VARCHAR NOT NULL, component_id INTEGER NOT NULL, yield_qty DOUBLE, yield_unit VARCHAR, weight_g DOUBLE, covers INTEGER, cost_per_unit_cents INTEGER, "version" INTEGER DEFAULT(1) NOT NULL, effective_from DATE);;
CREATE TABLE frostings(id INTEGER PRIMARY KEY, slug VARCHAR NOT NULL UNIQUE, "name" VARCHAR NOT NULL, kind VARCHAR NOT NULL, upcharge_cents INTEGER NOT NULL, color VARCHAR, whipped_at VARCHAR, on_hand_kg DOUBLE, covers_estimate INTEGER, active BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL);;
CREATE TABLE doughs(id INTEGER PRIMARY KEY, slug VARCHAR NOT NULL UNIQUE, "name" VARCHAR NOT NULL, kind VARCHAR NOT NULL, base_price_cents INTEGER NOT NULL, note VARCHAR, color VARCHAR, fried_at VARCHAR, batch_code VARCHAR, active BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL);;
CREATE TABLE toppings(id INTEGER PRIMARY KEY, slug VARCHAR NOT NULL UNIQUE, "name" VARCHAR NOT NULL, bin VARCHAR, upcharge_cents INTEGER NOT NULL, unit VARCHAR DEFAULT('kg'), on_hand DOUBLE, used_today DOUBLE, reorder_point DOUBLE, active BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL);;
CREATE TABLE day_closes(id INTEGER DEFAULT(nextval('seq_day_closes')) PRIMARY KEY, business_date DATE NOT NULL UNIQUE, closed_at TIMESTAMP DEFAULT(current_timestamp), shells_fried INTEGER NOT NULL, shells_left INTEGER NOT NULL, wasted_qty INTEGER NOT NULL);;
CREATE TABLE component_stock(id INTEGER PRIMARY KEY, component_type VARCHAR NOT NULL, component_id INTEGER NOT NULL, business_date DATE NOT NULL, qty_made INTEGER, qty_used INTEGER, qty_remaining INTEGER, unit VARCHAR DEFAULT('each'), sold_out_at VARCHAR, qty_wasted INTEGER DEFAULT(0));;
CREATE TABLE delivery_zones(id INTEGER PRIMARY KEY, zip VARCHAR NOT NULL UNIQUE, "name" VARCHAR, fee_cents INTEGER DEFAULT(400) NOT NULL, active BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL);;
CREATE TABLE purchase_orders(id INTEGER DEFAULT(nextval('seq_purchase_orders')) PRIMARY KEY, supplier_id INTEGER NOT NULL, ordered_at DATE NOT NULL, expected_at DATE, received_at DATE, status VARCHAR DEFAULT('open') NOT NULL, FOREIGN KEY (supplier_id) REFERENCES suppliers(id));;
CREATE TABLE pos_shifts(id INTEGER DEFAULT(nextval('seq_pos_shifts')) PRIMARY KEY, staff_id INTEGER, terminal VARCHAR, opened_at TIMESTAMP, closed_at TIMESTAMP, opening_float_cents INTEGER DEFAULT(0), counted_cents INTEGER, variance_cents INTEGER, FOREIGN KEY (staff_id) REFERENCES staff(id));;
CREATE TABLE ingredients(id INTEGER DEFAULT(nextval('seq_ingredients')) PRIMARY KEY, "name" VARCHAR NOT NULL, supplier_id INTEGER, unit VARCHAR NOT NULL, qty_on_hand DOUBLE DEFAULT(0) NOT NULL, reorder_point DOUBLE, last_cost_cents INTEGER, used_by VARCHAR, status VARCHAR DEFAULT('ok') NOT NULL, FOREIGN KEY (supplier_id) REFERENCES suppliers(id));;
CREATE TABLE delivery_slots(id INTEGER DEFAULT(nextval('seq_delivery_slots')) PRIMARY KEY, zone_id INTEGER, business_date DATE NOT NULL, starts_at VARCHAR, ends_at VARCHAR, capacity INTEGER DEFAULT(8) NOT NULL, booked INTEGER DEFAULT(0) NOT NULL, FOREIGN KEY (zone_id) REFERENCES delivery_zones(id));;
CREATE TABLE component_batches(id INTEGER DEFAULT(nextval('seq_component_batches')) PRIMARY KEY, component_type VARCHAR NOT NULL, component_id INTEGER NOT NULL, batch_code VARCHAR, started_at TIMESTAMP, ended_at TIMESTAMP, qty_made INTEGER, qty_wasted INTEGER DEFAULT(0), staff_id INTEGER, FOREIGN KEY (staff_id) REFERENCES staff(id));;
CREATE TABLE builds(id INTEGER DEFAULT(nextval('seq_builds')) PRIMARY KEY, "name" VARCHAR, dough_id INTEGER NOT NULL, is_custom BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, is_combo_of_day BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, featured_on DATE, price_cents_override INTEGER, created_by VARCHAR, blurb VARCHAR, created_at TIMESTAMP DEFAULT(current_timestamp), FOREIGN KEY (dough_id) REFERENCES doughs(id));;
CREATE TABLE recipe_items(id INTEGER DEFAULT(nextval('seq_recipe_items')) PRIMARY KEY, recipe_id INTEGER NOT NULL, ingredient_id INTEGER NOT NULL, qty DOUBLE NOT NULL, unit VARCHAR NOT NULL, FOREIGN KEY (recipe_id) REFERENCES recipes(id), FOREIGN KEY (ingredient_id) REFERENCES ingredients(id));;
CREATE TABLE purchase_order_items(id INTEGER DEFAULT(nextval('seq_purchase_order_items')) PRIMARY KEY, purchase_order_id INTEGER NOT NULL, ingredient_id INTEGER NOT NULL, qty_ordered DOUBLE NOT NULL, unit_cost_cents INTEGER NOT NULL, FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders(id), FOREIGN KEY (ingredient_id) REFERENCES ingredients(id));;
CREATE TABLE ingredient_lots(id INTEGER DEFAULT(nextval('seq_ingredient_lots')) PRIMARY KEY, ingredient_id INTEGER NOT NULL, lot_code VARCHAR NOT NULL, received_at DATE, expires_on DATE, qty_received DOUBLE, qty_remaining DOUBLE, purchase_order_id INTEGER, FOREIGN KEY (ingredient_id) REFERENCES ingredients(id));;
CREATE TABLE customers(id INTEGER DEFAULT(nextval('seq_customers')) PRIMARY KEY, "name" VARCHAR, email VARCHAR, phone VARCHAR, zip VARCHAR, street VARCHAR, channel VARCHAR DEFAULT('retail') NOT NULL, terms VARCHAR, invoice_status VARCHAR, loyalty_stamps INTEGER DEFAULT(0), orders_count INTEGER DEFAULT(0), usual_build_id INTEGER, first_order_at TIMESTAMP, lifetime_cents INTEGER DEFAULT(0), subscription_id INTEGER, FOREIGN KEY (usual_build_id) REFERENCES builds(id));;
CREATE TABLE build_components(id INTEGER DEFAULT(nextval('seq_build_components')) PRIMARY KEY, build_id INTEGER NOT NULL, component_type VARCHAR NOT NULL, component_id INTEGER NOT NULL, "position" INTEGER DEFAULT(0) NOT NULL, FOREIGN KEY (build_id) REFERENCES builds(id));;
CREATE TABLE orders(id INTEGER DEFAULT(nextval('seq_orders')) PRIMARY KEY, code VARCHAR NOT NULL UNIQUE, customer_id INTEGER, channel VARCHAR DEFAULT('web') NOT NULL, fulfillment VARCHAR NOT NULL, zip VARCHAR, slot_label VARCHAR, status VARCHAR DEFAULT('paid') NOT NULL, subtotal_cents INTEGER NOT NULL, fee_cents INTEGER DEFAULT(0) NOT NULL, total_cents INTEGER NOT NULL, placed_at TIMESTAMP DEFAULT(current_timestamp), FOREIGN KEY (customer_id) REFERENCES customers(id));;
CREATE TABLE subscriptions(id INTEGER DEFAULT(nextval('seq_subscriptions')) PRIMARY KEY, customer_id INTEGER NOT NULL, build_id INTEGER, cadence VARCHAR, standing_qty INTEGER, window_label VARCHAR, build_label VARCHAR, price_cents INTEGER, ytd_cents INTEGER DEFAULT(0), next_date DATE, paused BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, FOREIGN KEY (customer_id) REFERENCES customers(id), FOREIGN KEY (build_id) REFERENCES builds(id));;
CREATE TABLE reviews(id INTEGER DEFAULT(nextval('seq_reviews')) PRIMARY KEY, order_id INTEGER NOT NULL, customer_id INTEGER, rating SMALLINT NOT NULL, "comment" VARCHAR, created_at TIMESTAMP DEFAULT(current_timestamp), FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (customer_id) REFERENCES customers(id));;
CREATE TABLE payments(id INTEGER DEFAULT(nextval('seq_payments')) PRIMARY KEY, order_id INTEGER NOT NULL, shift_id INTEGER, "method" VARCHAR NOT NULL, amount_cents INTEGER NOT NULL, tip_cents INTEGER DEFAULT(0), captured_at TIMESTAMP DEFAULT(current_timestamp), FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (shift_id) REFERENCES pos_shifts(id));;
CREATE TABLE order_items(id INTEGER DEFAULT(nextval('seq_order_items')) PRIMARY KEY, order_id INTEGER NOT NULL, build_id INTEGER, pack VARCHAR DEFAULT('single') NOT NULL, qty INTEGER DEFAULT(1) NOT NULL, unit_price_cents INTEGER NOT NULL, swap_of_item_id INTEGER, FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (build_id) REFERENCES builds(id));;

